parameters.jsCode:
const input = $input.first().json;

const workflow =
  input.workflow ?? {};

const execution =
  input.execution ?? {};

const error =
  execution.error ??
  input.error ??
  {};

const workflowName =
  workflow.name ??
  'Unknown workflow';

const executionId =
  execution.id ??
  input.executionId ??
  '';

const lastNode =
  execution.lastNodeExecuted ??
  input.lastNodeExecuted ??
  '';

const message =
  error.message ??
  input.message ??
  'Unknown workflow error';

return [
  {
    json: {
      workflow_name: workflowName,
      execution_id:
        String(executionId),

      last_node:
        String(lastNode),

      error_message:
        String(message),

      execution_url:
        execution.url ?? '',

      details: input,

      db_payload: {
        workflow_name: workflowName,
        execution_id:
          String(executionId),

        last_node:
          String(lastNode),

        error_message:
          String(message),

        execution_url:
          execution.url ?? '',

        details: input,
      },
    },
  },
];

